const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/fscache";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  const p = path.join(dir, file);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text);
}
function vitest(args) {
  const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", ...args], {
    cwd: dir,
    encoding: "utf8",
    env: { ...process.env, NO_COLOR: "1", CI: "1" },
    timeout: 40000,
  });
  return { status: r.status, out: (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "") };
}
function filesIn(d) {
  if (!fs.existsSync(d)) return 0;
  return fs.readdirSync(d, { recursive: true }).filter((f) => fs.statSync(path.join(d, f)).isFile()).length;
}

write("helper.mjs", "export const add = (a, b) => a + b\n");
write("math.test.mjs", [
  "import { test, expect } from 'vitest'",
  "import { add } from './helper.mjs'",
  "test('adds', () => { expect(add(1, 2)).toBe(3) })",
].join("\n") + "\n");

// Run 1: the old name, experimental.fsModuleCache, must persist the cache on both versions.
const oldCache = path.join(dir, "cache-old");
write("old.config.mjs", "export default { test: { experimental: { fsModuleCache: true, fsModuleCachePath: " + JSON.stringify(oldCache) + " } } }\n");
const r1 = vitest(["run", "--config", "old.config.mjs"]);
console.log(r1.out);
if (r1.status !== 0 || filesIn(oldCache) === 0) {
  console.error("ERROR: experimental.fsModuleCache run failed or wrote no cache (exit " + r1.status + ")");
  process.exit(2);
}

// Run 2: the same settings under the top-level fsModuleCache option.
const newCache = path.join(dir, "cache-new");
write("new.config.mjs", "export default { test: { fsModuleCache: true, fsModuleCachePath: " + JSON.stringify(newCache) + " } }\n");
const r2 = vitest(["run", "--config", "new.config.mjs"]);
console.log(r2.out);
if (r2.status !== 0) {
  console.error("ERROR: top-level fsModuleCache run exited " + r2.status);
  process.exit(2);
}
const n = filesIn(newCache);
if (n > 0) {
  console.log("PASS: top-level fsModuleCache: true wrote " + n + " cache files to fsModuleCachePath");
  process.exit(0);
}
console.error("FAIL: top-level fsModuleCache: true was ignored and no module cache was written");
process.exit(1);

